def longest_palindrome(s):
    """Return the leftmost longest palindromic substring of s in O(n)."""
    if not s:
        return ""
    t, p = _manacher(s)
    best_len, best_center = 0, 0
    for i, r in enumerate(p):
        # r - 1 is the palindrome length in the original string.
        if r - 1 > best_len:
            best_len = r - 1
            best_center = i
    start = (best_center - p[best_center]) // 2
    return s[start : start + best_len]


def palindrome_radii(s):
    """Radii array over the transformed string '#a#b#...#'.

    p[i] is such that t[i-p[i] .. i+p[i]] is a maximal palindromic
    substring of t; the corresponding palindrome length in s is p[i] - 1.
    """
    return _manacher(s)[1]


def _manacher(s):
    t = "#" + "#".join(s) + "#"
    m = len(t)
    p = [0] * m
    center = right = 0
    for i in range(m):
        if i < right:
            p[i] = min(right - i, p[2 * center - i])
        while i - p[i] - 1 >= 0 and i + p[i] + 1 < m and t[i - p[i] - 1] == t[i + p[i] + 1]:
            p[i] += 1
        if i + p[i] > right:
            center, right = i, i + p[i]
    return t, p

